1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { normalizePath } from "@/lib/agent";
4	
5	export const dynamic = "force-dynamic";
6	
7	type Snapshot = { source: Record<string, string>; build: Record<string, string> };
8	
9	function toRows(
10	  files: Record<string, string> | undefined,
11	  projectId: string,
12	  kind: "source" | "build",
13	) {
14	  return Object.entries(files ?? {})
15	    .filter(([path]) => normalizePath(path) !== null)
16	    .map(([path, content]) => ({ projectId, path, content, published: false, kind }));
17	}
18	
19	// Rolling back is free — it's not a generation, just restoring a snapshot
20	// this project already paid for when the build ran. Restoring both the
21	// source AND the already-compiled build output means the preview is correct
22	// immediately, with no re-build needed (and no chance of that re-build
23	// failing on an otherwise-fine rollback).
24	export async function POST(
25	  _req: Request,
26	  { params }: { params: Promise<{ id: string; buildId: string }> },
27	) {
28	  const user = await requireUser().catch(() => null);
29	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
30	  const { id, buildId } = await params;
31	
32	  const build = await db.build.findFirst({
33	    where: { id: buildId, projectId: id, status: "SUCCEEDED", project: { userId: user.id } },
34	  });
35	  if (!build || !build.filesSnapshot) {
36	    return Response.json({ error: "Checkpoint not found." }, { status: 404 });
37	  }
38	
39	  const snapshot = build.filesSnapshot as unknown as Snapshot;
40	  const sourceRows = toRows(snapshot.source, id, "source");
41	  const buildRows = toRows(snapshot.build, id, "build");
42	
43	  await db.$transaction([
44	    db.projectFile.deleteMany({ where: { projectId: id, published: false, kind: "source" } }),
45	    db.projectFile.deleteMany({ where: { projectId: id, published: false, kind: "build" } }),
46	    ...(sourceRows.length > 0 ? [db.projectFile.createMany({ data: sourceRows })] : []),
47	    ...(buildRows.length > 0 ? [db.projectFile.createMany({ data: buildRows })] : []),
48	    db.project.update({ where: { id }, data: { updatedAt: new Date() } }),
49	  ]);
50	
51	  return Response.json({ ok: true, filesRestored: sourceRows.length });
52	}
