49	/**
50	 * Rename. Name only.
51	 *
52	 * THE SLUG IS DELIBERATELY NOT REGENERATED HERE.
53	 *
54	 * `slug` is the published address (`<slug>.kodely.site`, and the row the public
55	 * site route resolves by). Renaming is a labelling act — the user is fixing what
56	 * their dashboard calls the thing — and it must not be able to move a live site
57	 * out from under its own URL. If rename re-slugged:
58	 *   - every existing inbound link, share, QR code, and search-engine result for
59	 *     the published site would 404, silently, with no redirect to fall back on;
60	 *   - the old slug is globally unique and would be released back into the pool,
61	 *     so someone else could later claim the exact URL the user just vacated —
62	 *     a URL takeover triggered by an action that looks purely cosmetic.
63	 *
64	 * The same rule applies to unpublished projects, on purpose. Making it
65	 * conditional ("re-slug only while it's still a draft") would mean the slug
66	 * shown in the dashboard silently changes for a draft but freezes at publish —
67	 * a rule nobody can predict from the UI, and one that changes a preview URL the
68	 * user may already have handed to someone. One rule, always true: a slug is
69	 * assigned once at creation and never moves.
70	 *
71	 * A user who genuinely wants a different address wants a different site, and
72	 * that is what POST (duplicate) gives them — a new slug, no lost links.
73	 */
74	export async function PATCH(req: Request, { params }: { params: Promise<{ id: string }> }) {
75	  const user = await requireUser().catch(() => null);
76	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
77	  const { id } = await params;
78	
79	  const body = (await req.json().catch(() => null)) as { name?: unknown } | null;
80	  if (typeof body?.name !== "string") {
81	    return Response.json({ error: "A name is required." }, { status: 400 });
82	  }
83	  // Trim, cap, then trim again — slicing at 80 can leave a trailing space.
84	  const name = body.name.trim().slice(0, NAME_MAX).trim();
85	  if (!name) {
86	    // The create route falls back to "Untitled site" for a missing name, but a
87	    // rename is an explicit act: silently renaming someone's site to a
88	    // placeholder because their input was blank is worse than refusing.
89	    return Response.json({ error: "A name is required." }, { status: 400 });
90	  }
91	
92	  // updateMany, not update: `update` can only filter on unique fields, so it
93	  // would have to take the id alone and check ownership in a second query.
94	  // Scoping by { id, userId } in ONE query is what makes a wrong-user id
95	  // indistinguishable from a nonexistent one.
96	  const { count } = await db.project.updateMany({
97	    where: { id, userId: user.id },
98	    data: { name },
99	  });
100	  if (count === 0) return Response.json({ error: "Project not found." }, { status: 404 });
101	
102	  return Response.json({ project: { id, name } });
103	}
