105	/**
106	 * Duplicate — "make a variant of this" without paying for a whole new
107	 * generation. Charges no credits because nothing is generated: this is a row
108	 * copy, no model call anywhere on the path.
109	 *
110	 * What is copied: the name (suffixed), and every DRAFT file.
111	 * What is NOT copied:
112	 *   - publish state. `publishedAt` stays null and no `published: true` rows are
113	 *     copied, so a duplicate cannot silently go live at a new URL. Going live is
114	 *     always an explicit act through the publish route.
115	 *   - messages and builds. The copy is a fresh starting point, not a forked
116	 *     history; carrying over another project's conversation and its build/cost
117	 *     records would misattribute both.
118	 *
119	 * Draft files are copied for BOTH kinds, not just `kind: "source"`. The editor's
120	 * preview reads draft `kind: "build"` rows (app/api/preview/[id]) — copying only
121	 * source would hand the user a duplicate that renders "Nothing built yet" and
122	 * force a paid rebuild to see it, which is precisely the cost this feature
123	 * exists to avoid. Both draft trees together are the complete working state.
124	 */
125	export async function POST(_req: Request, { params }: { params: Promise<{ id: string }> }) {
126	  const user = await requireUser().catch(() => null);
127	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
128	  const { id } = await params;
129	
130	  const source = await db.project.findFirst({
131	    where: { id, userId: user.id },
132	    include: { files: { where: { published: false } } },
133	  });
134	  if (!source) return Response.json({ error: "Project not found." }, { status: 404 });
135	
136	  // Budget for the suffix before truncating, so the copy marker always survives
137	  // rather than being the part that gets sliced off an already-long name.
138	  const SUFFIX = " (copy)";
139	  const name = source.name.slice(0, NAME_MAX - SUFFIX.length).trim() + SUFFIX;
140	
141	  // The project row and its files are created in one transaction: a project
142	  // that exists with an empty file tree is a broken duplicate, and worse than
143	  // no duplicate at all.
144	  //
145	  // Retry wraps the WHOLE transaction. slugify()'s random suffix makes a
146	  // collision unlikely but not impossible, and a failed statement aborts the
147	  // surrounding Postgres transaction — so retrying the create in place would
148	  // run inside a poisoned transaction.
149	  let copy: { id: string; name: string; slug: string } | null = null;
150	  for (let attempt = 0; attempt < 5; attempt++) {
151	    try {
152	      copy = await db.$transaction(async (tx) => {
153	        const created = await tx.project.create({
154	          data: { userId: user.id, name, slug: slugify(name) },
155	        });
156	        if (source.files.length > 0) {
157	          await tx.projectFile.createMany({
158	            data: source.files.map((f) => ({
159	              projectId: created.id,
160	              path: f.path,
161	              content: f.content,
162	              published: false,
163	              kind: f.kind,
164	            })),
165	          });
166	        }
167	        return created;
168	      });
169	      break;
170	    } catch (err) {
171	      if (isUniqueViolation(err) && attempt < 4) continue;
172	      throw err;
173	    }
174	  }
175	  if (!copy) return Response.json({ error: "Couldn't duplicate this site." }, { status: 500 });
176	
177	  // A duplicate really is a project created, so it belongs in the same funnel.
178	  // EVENTS is a closed vocabulary by design (see lib/events.ts), so the copy is
179	  // distinguished by a prop rather than by inventing a name.
180	  track(EVENTS.projectCreated, {
181	    userId: user.id,
182	    props: { projectId: copy.id, source: "duplicate", sourceProjectId: source.id },
183	  });
184	
185	  return Response.json({ project: copy });
186	}
