     1	import Stripe from "stripe";
     2	
     3	// ── Money-path safety rules for this file ──────────────────────────────────
     4	// 1. Credit packs are a fixed server-side table, keyed by an opaque pack id.
     5	//    A client can only ever say WHICH pack it wants — never an amount, a
     6	//    price, or a credit count. This is the same class of bug that hit Nxeon's
     7	//    hosting checkout (displayed price != charged price); the fix there was
     8	//    "never trust a client-supplied number", and it applies here identically.
     9	// 2. Credits are granted ONLY from the webhook, after Stripe confirms payment
    10	//    — never from the client-side checkout-success redirect, which a user can
    11	//    hit or forge without ever having paid.
    12	// 3. Every webhook event is idempotency-guarded via StripeEvent (see schema)
    13	//    — Stripe retries on any non-2xx, so this must be safe to receive twice.
    14	
    15	export type CreditPack = {
    16	  id: string;
    17	  credits: number;
    18	  priceUsdCents: number;
    19	  label: string;
    20	};
    21	
    22	// $1 = 500 credits list price (matches MICROS_PER_CREDIT in lib/credits.ts —
    23	// 500 credits * 2000 micros = $1.00), packs get a modest discount at volume.
    24	export const CREDIT_PACKS: CreditPack[] = [
    25	  { id: "starter", credits: 500, priceUsdCents: 900, label: "500 credits — $9" },
    26	  { id: "builder", credits: 2500, priceUsdCents: 4000, label: "2,500 credits — $40" },
    27	  { id: "pro", credits: 6000, priceUsdCents: 9000, label: "6,000 credits — $90" },
    28	];
    29	
    30	export function getPack(packId: string): CreditPack | undefined {
    31	  return CREDIT_PACKS.find((p) => p.id === packId);
    32	}
    33	
    34	/** True once real Stripe keys are configured. Billing UI/routes degrade gracefully until then. */
    35	export function billingEnabled(): boolean {
    36	  return !!process.env.STRIPE_SECRET_KEY && !!process.env.STRIPE_WEBHOOK_SECRET;
    37	}
    38	
    39	let client: Stripe | null = null;
    40	
    41	export function stripe(): Stripe {
    42	  if (!process.env.STRIPE_SECRET_KEY) {
    43	    throw new Error("Stripe is not configured (STRIPE_SECRET_KEY unset).");
    44	  }
    45	  if (!client) client = new Stripe(process.env.STRIPE_SECRET_KEY);
    46	  return client;
    47	}

1	import { db } from "./db";
2	import { MODEL_RATES } from "./models";
3	
4	// ── The anti-bill-shock contract ──────────────────────────────────────────
5	// 1. A credit is a fixed, published amount of real model spend. No mystery units.
6	// 2. We charge from METERED tokens after a build succeeds — never a flat guess.
7	// 3. A build that fails is recorded with its true cost and charged ZERO.
8	// This is Kodely's clearest wedge against the category (see the board's
9	// "credit bill-shock" differentiation cards), so it lives in one small module.
10	
11	/** One credit = $0.002 of underlying model spend (500 credits = $1). */
12	export const MICROS_PER_CREDIT = 2_000;
13	
14	/**
15	 * New accounts start with enough to build and iterate on a real page.
16	 * Sized from measured real costs (2026-08-17): a full first build runs
17	 * ~$0.29 (144 credits), a follow-up edit ~$0.34 (172 credits) on Sonnet 5 —
18	 * 750 covers roughly one build plus 2-3 real edits.
19	 */
20	export const SIGNUP_GRANT = 750;
21	
22	export type Usage = {
23	  inputTokens: number;
24	  outputTokens: number;
25	  cacheReadTokens: number;
26	  cacheWriteTokens: number;
27	};
28	
29	/**
30	 * Micro-dollars of real model spend for a given usage on a given model.
31	 * MODEL_RATES stores USD per MILLION tokens, which — numerically — is
32	 * already USD-per-token expressed in micro-dollars (1e-6 USD = 1 microUSD).
33	 * So `rate * tokens` IS the cost in micros directly; do NOT also divide by
34	 * 1e6, that computes cost in whole dollars instead and silently floors every
35	 * build under $0.50 to 0 (which is exactly the bug this comment replaced —
36	 * caught 2026-08-17 when a real ~$0.22 build was charged only 1 credit).
37	 */
38	export function costMicros(model: string, usage: Usage): number {
39	  const rate = MODEL_RATES[model] ?? MODEL_RATES.default;
40	  const perToken = (perMTok: number, tokens: number) => perMTok * tokens;
41	  return Math.round(
42	    perToken(rate.input, usage.inputTokens) +
43	      perToken(rate.output, usage.outputTokens) +
44	      perToken(rate.cacheRead, usage.cacheReadTokens) +
45	      perToken(rate.cacheWrite, usage.cacheWriteTokens),
46	  );
