3	// Credits already cap spend per build, but nothing stops a broken or
4	// malicious client from firing many rapid requests before a human notices —
5	// and a free, unmetered *.kodely.site subdomain is a spam/phishing vector
6	// independent of credit spend. These are coarse, cheap safety nets, not a
7	// content-moderation system (there is no classifier here — a page can still
8	// be abusive content and pass both checks; that's a separate, harder problem
9	// left for a dedicated moderation pass, not faked here with a weak heuristic).
10	
11	const GENERATE_LIMIT = 20; // per user, per rolling hour
12	const PUBLISH_LIMIT = 15; // new (first-time) publishes per user, per rolling day
13	const ENHANCE_LIMIT = 40; // per user, per rolling hour
14	
15	export async function checkGenerateRateLimit(
16	  userId: string,
17	): Promise<{ allowed: boolean; retryAfterSeconds?: number }> {
18	  const since = new Date(Date.now() - 60 * 60_000);
19	  const count = await db.build.count({
20	    where: { project: { userId }, createdAt: { gte: since } },
21	  });
22	  if (count < GENERATE_LIMIT) return { allowed: true };
23	  return { allowed: false, retryAfterSeconds: 3600 };
24	}
25	
26	export async function checkPublishRateLimit(
27	  userId: string,
28	): Promise<{ allowed: boolean; retryAfterSeconds?: number }> {
29	  const since = new Date(Date.now() - 24 * 60 * 60_000);
30	  // Counts DISTINCT projects touched by a publish in the window, not publish
31	  // events — republishing the same project repeatedly still counts once.
32	  // That's the right shape: the abuse case is many distinct spam subdomains,
33	  // not heavy iteration on one real site (which credits already gate).
34	  const count = await db.project.count({
35	    where: { userId, publishedAt: { gte: since } },
36	  });
37	  if (count < PUBLISH_LIMIT) return { allowed: true };
38	  return { allowed: false, retryAfterSeconds: 86_400 };
39	}
