465	// ── Misc ──────────────────────────────────────────────────────────────────
466	
467	/**
468	 * Behind the Cloudflare -> host-nginx -> VM-nginx chain, req.url is the
469	 * internal 127.0.0.1:PORT the proxy forwards to, and X-Forwarded-Proto gets
470	 * clobbered by the Flexible-SSL hops. Same derivation the Google OAuth routes
471	 * use — the redirect_uri must match byte-for-byte across start and callback.
472	 */
473	export function originFromRequest(req: Request): string {
474	  const host = req.headers.get("host");
475	  if (!host) return new URL(req.url).origin;
476	  return `https://${host}`;
477	}
