    43	    return Response.json({ error: "Connect an account first." }, { status: 409 });
    44	  }
    45	
    46	  const readyAt = pending.createdAt.getTime() + UNVERIFIED_HOLD_HOURS * 3_600_000;
    47	  if (Date.now() < readyAt) {
    48	    return Response.json(
    49	      { error: "Not ready yet.", readyAt: new Date(readyAt).toISOString() },
    50	      { status: 425 },
    51	    );
    52	  }
    53	
    54	  const hash = hashFromPendingReason(pending.reason);
    55	  if (hash === null) {
    56	    console.error(`[rewards] malformed pending reason for user ${user.id}: ${pending.reason}`);
    57	    return Response.json({ error: "Rewards are unavailable right now." }, { status: 503 });
    58	  }
    59	
    60	  const result = await grantReward(user.id, platform, hash);
    61	  if (!result.ok) {
    62	    const status =
    63	      result.reason === "already_claimed" || result.reason === "identity_already_used"
    64	        ? 409
    65	        : result.reason === "velocity_tripped"
    66	          ? 429
    67	          : 503;
    68	    return Response.json({ error: messageFor(result.reason), state: result.reason }, { status });
    69	  }
    70	
    71	  return Response.json({ state: "claimed", credits: result.credits });
    72	}
    73	
    74	function messageFor(reason: string): string {
    75	  switch (reason) {
    76	    case "already_claimed":
    77	      return "You've already claimed this one.";
    78	    case "identity_already_used":
    79	      return "That account has already been used for this reward.";
    80	    case "velocity_tripped":
    81	      return "Reward claims are paused for a moment. Try again shortly.";
    82	    default:
    83	      return "Rewards are unavailable right now.";
    84	  }
    85	}

