146	/**
147	 * Turn an SDK result into the usage event the charging path expects.
148	 *
149	 * IMPORTANT — what this cost means. On the subscription there is no metered
150	 * per-build charge, so this is an IMPUTED cost: the real tokens this build
151	 * consumed, priced at the API rate card. It is what the build WOULD have cost
152	 * on metered billing, not money that left an account.
153	 *
154	 * That is deliberately more useful than reporting zeros. Zeroed usage made
155	 * every SDK build cost exactly 1 credit (the floor) and flatlined the
156	 * cost/margin dashboard — which is the instrument for the board's "riskiest
157	 * assumption #1", whether infra can beat credit economics. With real token
158	 * counts the credit meter, the ledger and the margin view all behave exactly
159	 * as they will on metered billing, which is what makes them testable now.
160	 *
161	 * `modelUsage` is the field the SDK documents as correct for token accounting:
162	 * it spans the main loop plus subagents and internal calls, where `usage`
163	 * covers only the main loop. It is cumulative per query() call, so it is read
164	 * once from the final result rather than summed across results.
165	 */
166	function meterUsage(message: { modelUsage?: Record<string, ModelUsage> }): {
167	  model: string;
168	  inputTokens: number;
169	  outputTokens: number;
170	  cacheReadTokens: number;
171	  cacheWriteTokens: number;
172	} {
173	  const usage = message.modelUsage ?? {};
174	  const totals = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
175	
176	  // The charging path takes ONE model string plus summed tokens, so attribute
177	  // the build to whichever model produced the most output tokens — output
178	  // dominates cost on every rate in the card. In practice Claude Code runs one
179	  // model for the main loop, so this is usually exact; when a cheap auxiliary
180	  // model also ran, its tokens are still counted, just priced at the main
181	  // model's rate. That errs toward over-billing, never under.
182	  let dominant = "";
183	  let mostOutput = -1;
184	
185	  for (const [model, u] of Object.entries(usage)) {
186	    totals.inputTokens += u.inputTokens ?? 0;
187	    totals.outputTokens += u.outputTokens ?? 0;
188	    totals.cacheReadTokens += u.cacheReadInputTokens ?? 0;
189	    totals.cacheWriteTokens += u.cacheCreationInputTokens ?? 0;
190	    if ((u.outputTokens ?? 0) > mostOutput) {
191	      mostOutput = u.outputTokens ?? 0;
192	      dominant = u.canonicalModel ?? model;
193	    }
194	  }
195	
196	  return {
197	    // No usage at all (a crashed or startup-error result) keeps the old
198	    // self-explaining tag, so a 1-credit build is visibly "no telemetry"
199	    // rather than looking like a genuinely free one.
200	    model: dominant ? toRateKey(dominant) : "claude-agent-sdk-subscription",
201	    ...totals,
202	  };
203	}
