222	async function readFileTree(dir: string, prefix = ""): Promise<FileMap> {
223	  const { readdir } = await import("node:fs/promises");
224	  const out: FileMap = {};
225	  const entries = await readdir(dir, { withFileTypes: true });
226	  for (const e of entries) {
227	    if (e.name === "node_modules" || e.name === ".git" || e.name.startsWith(".")) continue;
228	    const rel = prefix ? `${prefix}/${e.name}` : e.name;
229	    const full = path.join(dir, e.name);
230	    if (e.isDirectory()) Object.assign(out, await readFileTree(full, rel));
231	    else out[rel] = await readFile(full, "utf8");
232	  }
233	  return out;
