250	): AsyncGenerator<AgentEvent> {
251	  // The SDK edits a real directory rather than calling tools over the wire,
252	  // so the project is materialised to a temp dir and diffed afterwards.
253	  assertSdkCredentials();
254	  const workDir = await mkdtemp(path.join(tmpdir(), "kodely-sdk-"));
255	
256	  try {
257	    await writeFileMap(workDir, opts.files);
258	
259	    // Reference library beside the project. Dot-prefixed so readFileTree()
260	    // below skips it — otherwise every generated site would gain ~460 files.
261	    await materializeAssets(workDir);
262	
263	    let imageNote = "";
264	    if (opts.image) {
265	      const ext = opts.image.mediaType.split("/")[1] ?? "png";
266	      await writeFile(path.join(workDir, `.reference.${ext}`), Buffer.from(opts.image.data, "base64"));
267	      imageNote = `\n\nA reference image was attached to this request — Read the file .reference.${ext} in this directory to see it, then use it as visual/style guidance.`;
268	    }
269	
270	    const historyText = opts.history.length
271	      ? `## Prior conversation on this project\n${opts.history
272	          .map((h) => `${h.role === "user" ? "User" : "You"}: ${h.content}`)
