274	      : "";
275	
276	    yield {
277	      type: "status",
278	      text: opts.kind === "create" ? "Building your site…" : "Applying your changes…",
279	    };
280	
281	    for await (const message of query({
282	      prompt: `${historyText}## Current request\n${opts.request}${imageNote}`,
283	      options: {
284	        cwd: workDir,
285	        systemPrompt: adaptPromptForSdk(systemPrompt),
286	        allowedTools: ["Read", "Write", "Edit", "Bash", "Glob", "Grep"],
287	        permissionMode: "acceptEdits",
288	      },
289	    })) {
290	      if (opts.signal?.aborted) break;
291	
292	      if (message.type === "assistant" && message.message?.content) {
293	        for (const block of message.message.content) {
294	          if ("text" in block && block.text) {
295	            yield { type: "text", text: block.text };
296	          } else if (block.type === "tool_use") {
297	            // The only live signal this engine gives. Files are diffed out of
298	            // the working directory AFTER query() finishes, so without this the
299	            // chat sits silent for the whole build and then dumps every file at
300	            // once. Narrating the tool calls is what makes the wait legible.
301	            const line = narrateTool(block.name, (block.input ?? {}) as Record<string, unknown>);
302	            if (line) yield { type: "progress", text: line };
303	          }
304	        }
305	      } else if (message.type === "result") {
306	        yield { type: "usage", ...meterUsage(message) };
307	      }
308	    }
309	
310	    if (opts.signal?.aborted) return;
311	
312	    // Diff the directory back into write/delete events so the caller persists
313	    // exactly what the API engine would have produced.
314	    const after = await readFileTree(workDir);
315	
316	    for (const [p, content] of Object.entries(after)) {
317	      if (p.startsWith(".reference.")) continue;
318	      const rel = safeRelPath(p);
319	      if (!rel) continue;
320	      if (opts.files[p] === content) continue; // unchanged
321	      if (await opts.onWrite(rel, content)) yield { type: "file", path: rel, action: "write" };
322	    }
323	    for (const p of Object.keys(opts.files)) {
324	      if (p in after) continue;
325	      const rel = safeRelPath(p);
326	      if (!rel) continue;
327	      if (await opts.onDelete(rel)) yield { type: "file", path: rel, action: "delete" };
328	    }
329	  } finally {
330	    // On Windows a just-exited child can hold the dir briefly (EBUSY); retry,
331	    // and never let cleanup failure mask a successful generation.
332	    try {
333	      await rm(workDir, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 });
334	    } catch {}
335	  }
336	}
